import {WORLDS,LESSONS,NOTES,SONGS} from './content.js';
import {STORAGE_KEY,fresh,parseNotes,points,completed,recommend,record,validateBackup} from './core.js';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=fresh(),storageProblem=false;try{const raw=localStorage.getItem(STORAGE_KEY);if(raw)state=validateBackup(JSON.parse(raw));}catch{storageProblem=true;}
let audioGeneration=0;
let page=['map','songs','fingers','lab','stamps','guide'].includes(location.hash.slice(1))?location.hash.slice(1):'map';
let world=0,chosenNote='B5',activeLesson=null,selectedSong=SONGS[0].id,segment='all',audio=null,playing=false,timers=[],nodes=[],loop=false,clickTrack=false,articulation='normal',composerBeat=1,toastTimer,importCandidate=null;
const SOURCE='https://www.yamaha.com/ja/musical_instrument_guide/recorder/play/play002.html';
const PDF='https://www.yamaha.com/ja/musical_instrument_guide/common/images/recorder/fingering_german.pdf';
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageProblem=false;}catch{storageProblem=true;toast('この端末に保存できません。設定からバックアップを保存してね。');}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function earnedPoints(){return points(state);}
function badge(r){return !r?'○ これから':r.rating===1?'↻ れんしゅう中':r.rating===2?'✓ できた':'★ ばっちり';}
function route(p){stopAudio();page=p;location.hash=p;render();$('#main').focus();}
const nav=[['map','◈','ぼうけんマップ'],['songs','♫','曲のひろば'],['fingers','☝','指づかい図かん'],['lab','⚗','つくる・調べる'],['stamps','✦','スタンプ帳']];
function shell(body){const xp=earnedPoints(),lv=Math.floor(xp/100)+1;return `<aside class="sidebar"><a class="brand" href="#map" data-page="map"><span class="brand-icon">♫</span><span>リコーダー<br><b>クエスト<span class="brand-star">✦</span></b></span></a><div class="instrument-pill">ソプラノ・ジャーマン式</div><nav aria-label="メインメニュー">${nav.map(([p,i,l])=>`<button class="nav-item ${page===p?'selected':''}" data-page="${p}" ${page===p?'aria-current="page"':''}><span aria-hidden="true">${i}</span>${l}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="practice-tip"><b>きょうも、自分のペースで。</b><p>できない日も、発見はある。<br>ひとつずつ進もう。</p></div><button class="nav-item ${page==='guide'?'selected':''}" data-page="guide"><span aria-hidden="true">⚙</span>先生へ・記録の設定</button></div></aside><div class="workspace"><header class="topbar"><span class="breadcrumb">音のぼうけん <span>/</span> ${nav.find(n=>n[0]===page)?.[2]||'先生へ・記録の設定'}</span><div class="player-meta"><span class="level-pill">Lv. ${lv}</span><b class="xp-pill">✦ ${xp} <small>ポイント</small></b><span class="avatar" aria-label="自分の学習">♪</span></div></header>${storageProblem?'<div class="storage-warning" role="alert">保存済みの記録を読み込めないか、この端末に保存できません。設定からバックアップを確認してください。</div>':''}<main id="main" tabindex="-1">${body}</main><footer>リコーダークエスト <span>｜</span> くらべるのは、きのうの自分。 <span>｜</span> 記録はこのブラウザに保存されます</footer></div><dialog id="lesson-dialog" aria-labelledby="lesson-title"></dialog><dialog id="confirm-dialog" aria-labelledby="confirm-title"></dialog>`;}
function heading(k,t,s){return `<div class="page-heading"><div><p class="eyebrow">${k}</p><h1>${t}</h1><p class="muted">${s}</p></div></div>`;}
function mapView(){const rec=recommend(state),w=WORLDS[world],list=LESSONS.filter(l=>l.world===world),done=completed(state);const here=list.filter(l=>(state.records[l.id]?.rating||0)>=2).length;return `${heading('LET’S PLAY','きょうは、どんな音に出会う？','１つのチャレンジは３〜５分。気になるところから始めてもいいよ。')}<div class="dashboard-top"><section class="next-quest"><div><span class="white-chip">✦ きみへのおすすめ</span><p class="next-label">${WORLDS[rec.lesson.world].title} ・ STEP ${String(rec.lesson.number).padStart(2,'0')}</p><h2>${esc(rec.lesson.title)}</h2><p>${esc(rec.lesson.goal)}</p><button class="button yellow" data-lesson="${rec.lesson.id}">このチャレンジをはじめる <span>→</span></button></div><div class="quest-emblem" aria-hidden="true"><span>♪</span><span>✦</span><b>${String(rec.lesson.number).padStart(2,'0')}</b><small>STEP</small></div></section><section class="progress-card"><span class="eyebrow">MY ADVENTURE</span><h2>ここまでの足あと</h2><div class="progress-summary"><div class="ring" style="--progress:${done/LESSONS.length*100}%"><b>${done}<small>/ ${LESSONS.length}</small></b></div><div><b>${Math.floor(earnedPoints()/100)+1}<small> レベル</small></b><p>${Object.values(state.records).filter(r=>r.rating===3).length} 個の「ばっちり」</p></div></div><p class="recommend-reason">${rec.reason}</p><button class="text-button" data-page="stamps">スタンプ帳をひらく ↗</button></section></div><div class="section-title"><div><h2>ぼうけんマップ</h2><span>学年は目安。おさらいも、先への挑戦も自由！</span></div><span class="count-pill">12 エリア</span></div><div class="world-grid">${WORLDS.map(x=>{const n=LESSONS.filter(l=>l.world===x.id&&(state.records[l.id]?.rating||0)>=2).length;return `<button class="world-card ${world===x.id?'active':''}" style="--world:${x.color}" data-world="${x.id}" aria-pressed="${world===x.id}"><span class="world-icon" aria-hidden="true">${x.icon}</span><span class="world-text"><small>AREA ${String(x.id+1).padStart(2,'0')} <span>${n}/8</span></small><b>${x.title}</b><span>${x.grade}</span></span><span class="mini-progress" style="--fill:${n/8*100}%"></span></button>`;}).join('')}</div><section class="area-panel" style="--world:${w.color}"><div class="area-heading"><div><span class="area-kicker">AREA ${String(world+1).padStart(2,'0')} <span>${w.grade}</span></span><h2>${w.icon} ${w.title}</h2><p>${w.sub}</p></div><div class="area-progress"><b>${here}<small> / 8 クリア</small></b><progress max="8" value="${here}" aria-label="このエリアの進み具合"></progress></div></div><div class="lesson-grid">${list.map(l=>{const r=state.records[l.id];return `<button class="lesson-card ${r?.rating>=2?'done':''}" data-lesson="${l.id}"><span class="step-round ${r?.rating>=2?'checked':''}">${r?.rating>=2?'✓':String(l.number).padStart(2,'0')}</span><span class="lesson-copy"><small>${l.minutes}分 ・ ${l.number===8?'まとめの挑戦':'小さな一歩'}</small><b>${l.title}</b><span>${badge(r)}</span></span><span class="lesson-arrow">›</span></button>`;}).join('')}</div></section>`;}
function fingering(note=chosenNote,compact=false){const [name,,pattern]=NOTES[note];const labels=['左・親指（うら０）','左・人さし指（１）','左・中指（２）','左・薬指（３）','右・人さし指（４）','右・中指（５）','右・薬指（６）','右・小指（７）'];return `<div class="fingering ${compact?'compact':''}"><div class="finger-title"><span class="eyebrow">GERMAN</span><h3>${name}</h3></div><div class="hole-list">${[...pattern].map((v,i)=>`<div class="hole-row ${i===4?'hand-break':''}"><span class="hole-number">${i}</span><span class="${i>=6?'double-holes':'single-hole'}">${i>=6?`<i class="hole ${v==='1'?'closed':''}"></i><i class="hole ${v==='1'?'closed':''}"></i>`:`<i class="hole ${v==='1'?'closed':v==='h'?'half':''}"></i>`}</span><span>${labels[i]}</span><span class="sr-only">${v==='1'?'閉じる':v==='h'?'少し開ける':'開ける'}</span></div>`).join('')}</div><div class="finger-legend"><span>● 閉じる</span><span>○ 開ける</span><span>◐ 少し開ける</span></div>${pattern[0]==='h'?'<p class="finger-tip">うら０は、小さなすきま。半分きっちり開けなくていいよ。</p>':''}<p class="finger-tip">自分の楽器の穴番号と見くらべよう。<br>右の親指は、うらで楽器を支えるよ。</p></div>`;}
const diatonic={C:0,D:1,E:2,F:3,G:4,A:5,B:6};
function staff(events,meter=4){let offset=0,measures=[[]];events.forEach((e,index)=>{let left=e.beats;while(left>0){const remaining=meter-offset;const duration=Math.min(left,remaining);measures.at(-1).push({...e,beats:duration,index,offset,tied:left!==e.beats||duration<left});offset+=duration;left-=duration;if(Math.abs(offset-meter)<.001){measures.push([]);offset=0;}}});if(!measures.at(-1).length)measures.pop();return `<div class="score-grid" aria-label="楽譜。音符を押すと指づかいを確認できます">${measures.map((m,mi)=>`<svg class="measure" viewBox="0 0 310 157" role="group" aria-label="${mi+1}小節"><text x="12" y="18" class="measure-number">${mi+1}</text>${[60,70,80,90,100].map(y=>`<line x1="12" x2="302" y1="${y}" y2="${y}" class="staff-line"/>`).join('')}<line x1="302" x2="302" y1="60" y2="100" class="bar-line"/>${mi===0?`<text x="14" y="94" class="clef">𝄞</text><text x="39" y="76" class="time-signature">${meter}</text><text x="39" y="94" class="time-signature">4</text>`:''}${m.map(e=>{const weight=m.reduce((a,n)=>a+Math.max(1,n.beats),0);const before=m.slice(0,m.indexOf(e)).reduce((a,n)=>a+Math.max(1,n.beats),0);const x=(mi===0?67:31)+before*(mi===0?225:263)/weight;const label=e.note==='R'?'休み':NOTES[e.note][0];const y=e.note==='R'?80:110-(diatonic[e.note[0]]+(Number(e.note.slice(1))-5)*7)*5;const down=y<80;const stemX=x+(down?-6:6),endY=y+(down?31:-31);return `<g class="score-note" data-note="${e.note}" data-event="${e.index}" role="button" tabindex="0" aria-label="${label}、${e.beats}拍"><rect class="note-hit" x="${x-15}" y="26" width="30" height="113" rx="9"/>${e.note==='R'?`<text x="${x-9}" y="91" class="rest">${e.beats>=4?'𝄻':e.beats>=2?'𝄼':e.beats<=.5?'𝄾':'𝄽'}</text>`:`${y>=110?Array.from({length:Math.floor((y-100)/10)},(_,i)=>`<line x1="${x-11}" x2="${x+11}" y1="${110+i*10}" y2="${110+i*10}" class="staff-line"/>`).join(''):y<=50?Array.from({length:Math.floor((60-y)/10)},(_,i)=>`<line x1="${x-11}" x2="${x+11}" y1="${50-i*10}" y2="${50-i*10}" class="staff-line"/>`).join(''):''}<ellipse cx="${x}" cy="${y}" rx="7" ry="5" transform="rotate(-18 ${x} ${y})" class="note-head ${e.beats>=2?'open':''}"/>${e.beats<4?`<line x1="${stemX}" x2="${stemX}" y1="${y}" y2="${endY}" class="stem"/>`:''}${e.beats<1?`<path d="M${stemX} ${endY} q 17 ${down?-3:3} 10 ${down?-20:20}" class="flag"/>${e.beats<=.25?`<path d="M${stemX} ${endY+(down?-7:7)} q 17 ${down?-3:3} 10 ${down?-20:20}" class="flag"/>`:''}`:''}${[1.5,3].includes(e.beats)?`<circle cx="${x+13}" cy="${y-3}" r="2.2"/>`:''}${e.tied?`<path d="M${x-10} ${y+15} q 10 9 20 0" class="tie"/>`:''}`}<text x="${x}" y="139" text-anchor="middle" class="note-label">${state.settings.names?(e.note==='R'?'休み':({C:'ド',D:'レ',E:'ミ',F:'ファ',G:'ソ',A:'ラ',B:'シ'}[e.note[0]]+(e.note.endsWith('6')?'↑':''))):''}</text></g>`;}).join('')}</svg>`).join('')}</div>`;}
function player(events,meter=4){return `<div class="audio-controls"><button class="button primary play-toggle" data-action="play">▶ お手本を聴く</button><button class="button secondary" data-action="stop">■ とめる</button><label class="tempo">速さ <input id="tempo" type="range" min="40" max="140" step="1" value="${state.settings.tempo}" aria-label="演奏の速さ"><output>${state.settings.tempo}</output></label><label class="check-inline"><input type="checkbox" id="loop" ${loop?'checked':''}>くり返す</label><label class="check-inline"><input type="checkbox" id="click-track" ${clickTrack?'checked':''}>拍の音</label><button class="text-button" data-action="names">音名を${state.settings.names?'かくす':'出す'}</button></div><div class="player-status" role="status" aria-live="polite">${meter}拍 数えてからスタート。お手本は音の高さ・長さを確かめる電子音です。</div>${staff(events,meter)}`;}
function currentEvents(){if(activeLesson)return parseNotes(activeLesson.notes);if(page==='lab')return state.composition;if(page==='songs'){const events=parseNotes(SONGS.find(s=>s.id===selectedSong).notes);if(segment==='all')return events;const start=Number(segment)*8;let b=0;return events.filter(e=>{const yes=b>=start&&b<start+8;b+=e.beats;return yes;});}return [{note:chosenNote,beats:2}];}
function currentMeter(){if(activeLesson)return activeLesson.world===6&&activeLesson.number===8?3:4;return page==='songs'?SONGS.find(s=>s.id===selectedSong).meter:4;}
function updateNote(note){if(!NOTES[note])return;chosenNote=note;$$('.live-fingering').forEach(e=>e.innerHTML=fingering(note,true));$$('[data-pick-note]').forEach(e=>e.setAttribute('aria-pressed',String(e.dataset.pickNote===note)));}
async function ctx(){if(!audio){const A=window.AudioContext||window.webkitAudioContext;if(!A)throw Error('このブラウザでは音を再生できません');audio=new A();}if(audio.state==='suspended')await audio.resume();return audio;}
function tone(note,when,duration,isClick=false){if(note==='R')return;const o=audio.createOscillator(),g=audio.createGain();o.type=isClick?'sine':'sine';o.frequency.value=isClick?1000:440*2**((NOTES[note][1]-69)/12);g.gain.setValueAtTime(0,when);g.gain.linearRampToValueAtTime(isClick?.09:.12,when+.012);g.gain.setValueAtTime(isClick?.09:.12,when+Math.max(.013,duration-.03));g.gain.linearRampToValueAtTime(0,when+duration);o.connect(g);g.connect(audio.destination);o.start(when);o.stop(when+duration+.02);nodes.push(o);o.onended=()=>{o.disconnect();g.disconnect();nodes=nodes.filter(n=>n!==o);};}
function stopAudio(){audioGeneration++;timers.forEach(clearTimeout);timers=[];for(const n of nodes){try{n.stop();}catch{}}nodes=[];playing=false;$$('.score-note').forEach(e=>e.classList.remove('sounding'));$$('.play-toggle').forEach(e=>{e.textContent='▶ お手本を聴く';e.disabled=false;});$$('.player-status').forEach(e=>e.textContent='とめました。ゆっくり何度でも試そう。');}
async function play(){stopAudio();const generation=audioGeneration;const events=currentEvents();if(!events.length){toast('まず音を入れてみよう。');return;}try{await ctx();if(generation!==audioGeneration)return;const beat=60/state.settings.tempo,meter=currentMeter(),start=audio.currentTime+.1;playing=true;$$('.play-toggle').forEach(e=>{e.disabled=true;e.textContent='♫ 再生中';});for(let i=0;i<meter;i++){tone('B5',start+i*beat,.055,true);timers.push(setTimeout(()=>$$('.player-status').forEach(e=>e.textContent=`じゅんび… ${i+1}`),100+i*beat*1000));}let time=meter*beat;events.forEach((e,i)=>{tone(e.note,start+time,e.beats*beat*(articulation==='short'?.4:articulation==='smooth'?.98:.85));timers.push(setTimeout(()=>{$$('.score-note').forEach(n=>n.classList.toggle('sounding',Number(n.dataset.event)===i));updateNote(e.note);$$('.player-status').forEach(n=>n.textContent=e.note==='R'?'お休み。拍を数えよう。':`${NOTES[e.note][0]} ・ ${e.beats}拍`);},100+time*1000));time+=e.beats*beat;});if(clickTrack){for(let i=meter;i<time/beat;i++)tone('B5',start+i*beat,.04,true);}timers.push(setTimeout(()=>{stopAudio();if(loop)play();else $$('.player-status').forEach(e=>e.textContent='最後まで聴けたね。次は自分の音で試そう。');},time*1000+200));}catch(e){stopAudio();toast(e.message||'音を再生できません。音量とブラウザの設定を確認してね。');}}
async function singleNote(n){stopAudio();const generation=audioGeneration;updateNote(n);try{await ctx();if(generation!==audioGeneration)return;tone(n,audio.currentTime+.02,.7);}catch(e){toast(e.message);}}
function openLesson(id){const l=LESSONS.find(l=>l.id===id);if(!l)return;stopAudio();activeLesson=l;const r=state.records[id];const note=parseNotes(l.notes).find(e=>e.note!=='R')?.note||'B5';chosenNote=note;const dialog=$('#lesson-dialog');dialog.innerHTML=`<div class="modal-header"><div><span class="eyebrow">${WORLDS[l.world].title} / STEP ${l.number}</span><h2 id="lesson-title">${l.title}</h2></div><button class="icon-button" data-action="close-lesson" aria-label="チャレンジを閉じる">×</button></div><div class="modal-body"><div class="lesson-goal"><span>きょうのミッション</span><b>${l.goal}</b><small>${l.minutes}分くらい ・ 何度やり直しても大丈夫</small></div><div class="lesson-layout"><div><h3>① ひとつずつ、やってみよう</h3><div class="microsteps">${l.steps.map((s,i)=>`<label><input type="checkbox" class="step-check"><span class="step-index">${i+1}</span><span>${s}</span></label>`).join('')}</div><div class="hint"><b>💡 こまったら</b><p>${l.tip}</p></div>${l.world===11&&l.number<=3?`<p><a class="button secondary" href="${PDF}" target="_blank" rel="noopener">メーカーのジャーマン式運指表 ↗</a></p><p class="muted">下の音は準備練習です。調べる半音・超高音の音源ではありません。</p>`:''}<h3>② 音を聴く・指をたしかめる</h3>${player(parseNotes(l.notes),currentMeter())}<div class="hint inquiry"><b>🔎 発見のたね</b><p>${l.question}</p></div></div><aside class="live-fingering">${fingering(note,true)}</aside></div><section class="reflection"><h3>③ ふりかえろう</h3><p class="success-criterion"><b>できたの目安</b> ${l.check}</p><fieldset class="rating"><legend>今の自分に近いものは？</legend><label><input name="rating" type="radio" value="1"><span>↻<b>むずかしい</b><small>ひとつ戻って練習</small></span></label><label><input name="rating" type="radio" value="2"><span>✓<b>できた！</b><small>目安をクリア</small></span></label><label><input name="rating" type="radio" value="3"><span>★<b>ばっちり！</b><small>もう一度もできた</small></span></label></fieldset><label class="field-label" for="reflection">気づいたこと・次に試したいこと（書けたら）</label><textarea id="reflection" maxlength="800" rows="2" placeholder="例：右の指を置くと、左の指がずれることに気づいた。">${esc(r?.reflection||'')}</textarea><p class="muted">自分でふりかえる記録です。音の自動採点ではありません。</p><div class="save-row"><span id="save-hint">「むずかしい」は途中でも記録できるよ。</span><button class="button primary" id="save-lesson" data-action="save-lesson" disabled>足あとをのこす ✦</button></div></section></div>`;dialog.showModal();}
function closeLesson(){stopAudio();$('#lesson-dialog').close();activeLesson=null;}
function checkLesson(){const rating=Number($('input[name="rating"]:checked')?.value||0);const all=$$('.step-check').every(e=>e.checked);$('#save-lesson').disabled=!rating||(rating>=2&&!all);$('#save-hint').textContent=rating>=2&&!all?'３つのステップを試したら、チェックを入れてね。':'くり返し練習してもポイントは重複しません。';}
function saveLesson(){if($('#save-lesson').disabled||!activeLesson)return;const l=activeLesson,rating=Number($('input[name="rating"]:checked').value),before=earnedPoints();record(state,l.id,rating,$('#reflection').value);save();const diff=earnedPoints()-before;closeLesson();render();toast(rating===1?'挑戦したことが一歩前進！おすすめにおさらいを用意したよ。':`足あとをのこしたよ！${diff>0?' ＋'+diff+'ポイント ✦':' 次も自分のペースで。'}`);}
function songsView(){const s=SONGS.find(s=>s.id===selectedSong),all=parseNotes(s.notes),total=all.reduce((n,e)=>n+e.beats,0);return `${heading('MUSIC LIBRARY','曲のひろば','聴く → 小分けに練習 → つなげる。好きな曲を自分の速さで。')}<div class="song-layout"><section class="song-list" aria-label="曲を選ぶ">${SONGS.map(s=>`<button class="song-item ${s.id===selectedSong?'active':''}" data-song="${s.id}" aria-pressed="${s.id===selectedSong}"><span class="song-icon" style="--world:${WORLDS[s.world].color}">♫</span><span><small>${s.kind} ・ AREA ${s.world+1}</small><b>${s.title}</b><small>${WORLDS[s.world].grade}</small></span></button>`).join('')}</section><section class="song-detail"><span class="eyebrow">${s.kind} ・ ${s.meter}拍子</span><h2>${s.title}</h2><p class="muted">${s.source}</p><div class="song-options"><label>練習するところ <select id="segment"><option value="all">１曲ぜんぶ</option>${Array.from({length:Math.ceil(total/8)},(_,i)=>`<option value="${i}" ${segment===String(i)?'selected':''}>${i*8+1}〜${Math.min(total,(i+1)*8)}拍</option>`).join('')}</select></label><label>音のつなぎ方 <select id="articulation"><option value="normal" ${articulation==='normal'?'selected':''}>ふつう</option><option value="short" ${articulation==='short'?'selected':''}>短く</option><option value="smooth" ${articulation==='smooth'?'selected':''}>なめらか</option></select></label></div><div class="score-with-fingers"><div>${player(currentEvents(),s.meter)}<div class="hint"><b>練習のコツ</b><p>① 音名で歌う　② 指だけ動かす　③ ゆっくり吹く。つまずいたら前後の２音に戻ろう。</p></div>${s.id==='frog'||s.id==='brother'?'<button class="button secondary" data-action="canon">♫ 輪唱を聴く（８拍あとに２人目）</button>':''}<button class="text-button" data-lesson="${LESSONS[s.world*8+7].id}">このエリアのまとめに挑戦 →</button></div><aside class="live-fingering">${fingering(chosenNote,true)}</aside></div></section></div>`;}
function fingersView(){return `${heading('FINGERING BOOK','指づかい図かん','音をえらぶと、指づかいと高さをたしかめられるよ。')}<div class="finger-book"><section><div class="note-picker">${Object.entries(NOTES).map(([k,n])=>`<button data-pick-note="${k}" aria-pressed="${k===chosenNote}"><span>♪</span><b>${n[0]}</b></button>`).join('')}</div><div class="hint"><b>指のやくそく</b><p>左手が上、右手が下。裏の穴は０、表は上から１〜７。６と７にある２つの小穴は、図が●●なら両方を閉じるよ。</p></div><h2>音がうまく出ないときは？</h2><details><summary>ピーッと高い音になる</summary><p>穴のすきまを一つずつ確認しよう。次に、息を少しやさしくして短く吹いてみよう。両方をいっぺんに変えず、一つずつ試そう。</p></details><details><summary>指を動かすと、音がまざる</summary><p>音を出さずに２つの指の形を交互につくろう。動かさない指はそのまま。ゆっくりできてから息を入れよう。</p></details><details><summary>高い音のすきまがわからない</summary><p>高いレは裏を全開。高いミからは裏に小さなすきまをつくるよ。図の◐は「半分の量」ではなく、少し開けるしるし。</p></details><details><summary>半音や、もっと高い音を調べたい</summary><p>この図かんは低いド〜高いソの自然音に対応。半音・超高音・替え指は、楽器に付属する説明書を先生と確認しよう。</p><a href="${PDF}" target="_blank" rel="noopener">ヤマハ・ジャーマン式の全音域の運指表 ↗</a></details><p class="source-note">参照：<a href="${SOURCE}" target="_blank" rel="noopener">ヤマハ「リコーダーの運指表」</a>。機種で運指が異なる場合は、付属の表を優先します。</p></section><aside class="live-fingering finger-large">${fingering(chosenNote)}</aside></div>`;}
function labView(){const notes=state.composition,total=notes.reduce((n,e)=>n+e.beats,0);return `${heading('SOUND LAB','つくる・調べる','「もし、こうしたら？」を音で試す場所。正解はひとつじゃないよ。')}<div class="lab-layout"><section class="composer"><span class="eyebrow">MY MELODY</span><h2>きみだけのメロディー</h2><label class="field-label" for="composition-title">曲の名前</label><input id="composition-title" maxlength="60" value="${esc(state.compositionTitle)}"><div class="composer-toolbar"><label>次に入れる音の長さ <select id="composer-beat">${[[.25,'¼拍'],[.5,'½拍'],[1,'１拍'],[1.5,'1½拍'],[2,'２拍'],[3,'３拍'],[4,'４拍']].map(([v,l])=>`<option value="${v}" ${v===composerBeat?'selected':''}>${l}</option>`).join('')}</select></label><span>${total}拍 ・ ${notes.length}/32音</span></div><div class="composer-keys">${Object.entries(NOTES).map(([k,n])=>`<button data-add-note="${k}" ${notes.length>=32?'disabled':''}>${n[0]}</button>`).join('')}<button data-add-note="R" ${notes.length>=32?'disabled':''}>休み</button></div><div class="composition-chips">${notes.length?notes.map((e,i)=>`<button data-remove-note="${i}" aria-label="${i+1}番目の${e.note==='R'?'休み':NOTES[e.note][0]}を削除">${e.note==='R'?'休':NOTES[e.note][0]}<small>${e.beats}拍 ×</small></button>`).join(''):'<p>まずはソ・ラ・シの３つから。上の音を押して入れよう。</p>'}</div>${notes.length?'<p class="muted">上の音のチップを押すと、その音を消せます。</p>':''}${player(notes)}<div class="hint inquiry"><b>今日の実験</b><p>最後の１音を変えてみよう。「まだ続きそう」「終わった感じ」の違いはある？</p></div></section><section class="research"><span class="eyebrow">DISCOVERY NOTE</span><h2>発見ノート</h2><label class="field-label" for="research-prompt">調べること</label><select id="research-prompt">${LESSONS.filter(l=>l.world===9).map(l=>`<option value="${l.id}">${l.title}</option>`).join('')}</select><p id="research-question">${LESSONS[72].question}</p><label class="field-label" for="research-note">予想 → 試したこと → 結果 → 次の問い</label><textarea id="research-note" rows="10" maxlength="1600" placeholder="予想：最後をソにすると…&#10;試したこと：…&#10;結果：…&#10;次は：…">${esc(state.notes['w10-1']||'')}</textarea><button class="button primary" data-action="save-research">発見をのこす</button><button class="text-button" data-lesson="w10-1">研究のチャレンジへ →</button></section></div>`;}
function stampsView(){const xp=earnedPoints(),done=completed(state),all=Object.entries(state.records).sort((a,b)=>b[1].date.localeCompare(a[1].date));return `${heading('MY COLLECTION','スタンプ帳','練習も、発見も、きみだけの大切な足あと。')}<div class="stat-row"><div><span>ぼうけんレベル</span><b>${Math.floor(xp/100)+1}</b><progress max="100" value="${xp%100}" aria-label="次のレベルまで"></progress><small>次のレベルまで ${100-xp%100} ポイント</small></div><div><span>ためたポイント</span><b>${xp}<small> pt</small></b><small>最高のふりかえりで１課題 最大30pt</small></div><div><span>クリアした挑戦</span><b>${done}<small> / 96</small></b><small>自分の「できた」を集めよう</small></div></div><div class="section-title"><h2>エリアのスタンプ</h2><span>エリアの８つをクリアすると色がつくよ</span></div><div class="stamp-grid">${WORLDS.map(w=>{const n=LESSONS.filter(l=>l.world===w.id&&(state.records[l.id]?.rating||0)>=2).length;return `<button class="stamp-card ${n===8?'earned':''}" data-world="${w.id}" style="--world:${w.color}"><span class="stamp-symbol">${w.icon}</span><b>${w.title}</b><small>${n===8?'✦ エリアクリア！':`${n}/8 ・ あと${8-n}チャレンジ`}</small></button>`;}).join('')}</div><h2>最近の足あと</h2>${all.length?`<div class="history">${all.slice(0,20).map(([id,r])=>`<article><span class="history-mark">${r.rating===3?'★':r.rating===2?'✓':'↻'}</span><div><button class="text-button" data-lesson="${id}">${LESSONS.find(l=>l.id===id).title}</button><p>${esc(r.reflection||'今日もひとつ、挑戦した。')}</p><small>${new Date(r.date).toLocaleDateString('ja-JP')} ・ ${badge(r)} ・ ${r.attempts}回挑戦</small></div></article>`).join('')}</div>`:'<div class="empty-state"><span>✦</span><h3>最初の足あとをのこそう</h3><p>むずかしかったことも、記録して大丈夫。</p><button class="button primary" data-lesson="w1-1">最初のチャレンジへ</button></div>'}`;}
function guideView(){return `${heading('FOR TEACHERS','先生へ・記録の設定','ジャーマン式ソプラノリコーダー／小学校３〜６年生＋発展')}<div class="guide-grid"><section class="panel"><h2>授業での使い方</h2><ol><li>全体で今日の音・聴きどころを確認（５分）。</li><li>おすすめや好きなエリアで個別練習（10〜15分）。</li><li>ペアで聴き、具体的な気づきを交換（５〜10分）。</li><li>曲・合奏・創作に戻って試す（10分）。</li><li>自己評価と次の一歩を記録（５分）。</li></ol><p>96課題・288の小ステップ。進度は学年で制限しません。難しいと回答すると直前の基礎を提案します。全課題は自由に閲覧できます。</p><h3>評価の位置づけ</h3><p>児童の自己評価です。マイクでの自動判定や成績評価ではありません。「できた」の目安を児童と共有し、音色・拍・姿勢は先生や友だちの聴取と合わせて確認してください。発展コースの完了は専門演奏家の技能認定を意味しません。</p><h3>授業の音環境</h3><p>お手本は電子音です。音色や息づかいのお手本は先生の実演も使ってください。端末の音量を下げ、お手本を聴く時間と吹く時間を分けると、教室で聴き取りやすくなります。</p></section><section class="panel"><h2>記録を持ち運ぶ</h2><p>このブラウザ内に保存します。名前・メール・学級は入力不要。別端末への自動同期や先生の一括閲覧はありません。共用端末では、使う人ごとにブラウザの利用環境を分けてください。</p><p>ブラウザのデータ削除で消えるため、ときどきバックアップを保存してください。別の端末では、そのファイルを読み込んで続けられます。</p><button class="button primary" data-action="export">↓ 学習記録をバックアップ</button><label class="button secondary file-button">↑ バックアップを読みこむ<input type="file" id="import-file" accept="application/json,.json"></label><p class="muted">読みこむ前に確認します。今の記録は置き換わります。</p><button class="text-button danger" data-action="reset">この端末の記録をリセット</button></section><section class="panel"><h2>教材と運指の範囲</h2><p>内蔵の運指図は低いド〜高いソの自然音12音。半音・超高音・替え指はメーカーの全音域運指表と楽器付属の説明書を使って先生と確認する発展課題です。機種による違いがある場合は付属表を優先します。</p><p>内蔵12曲はオリジナル練習曲８曲と、古い旋律を独自に入力した４曲。現行教科書の曲・歌詞・市販の編曲譜は収録していません。</p><ul><li><a href="${SOURCE}" target="_blank" rel="noopener">ヤマハ：リコーダーの運指表</a></li><li><a href="${PDF}" target="_blank" rel="noopener">ジャーマン式の全音域運指表（PDF）</a></li><li><a href="https://www.yamaha.com/ja/musical_instrument_guide/recorder/play/" target="_blank" rel="noopener">ヤマハ：構え方と息づかい</a></li></ul><p class="muted">参照確認：2026年９月10日。小ステップの構成・練習フレーズは本サイト独自です。</p></section><section class="panel"><h2>学びの見取り</h2><table><thead><tr><th>観点</th><th>確かめること</th></tr></thead><tbody><tr><td>音づくり</td><td>穴を閉じ、息を調整して音を保てる</td></tr><tr><td>技能</td><td>指・舌・拍をそろえ、同じように再現できる</td></tr><tr><td>表現</td><td>曲のまとまりを捉え、意図を音にできる</td></tr><tr><td>探究・協働</td><td>条件を比べ、気づきを説明し、聴き合える</td></tr></tbody></table><p>ポイントは挑戦10pt、できた20pt、ばっちり30ptの最高到達分。くり返しで増やせず、苦手に戻っても獲得済みポイントは減りません。ランキングはありません。</p></section></div>`;}
function render(){const views={map:mapView,songs:songsView,fingers:fingersView,lab:labView,stamps:stampsView,guide:guideView};$('#app').innerHTML=shell(views[page]());$('#lesson-dialog').addEventListener('cancel',()=>{stopAudio();activeLesson=null;});$('#confirm-dialog').addEventListener('cancel',()=>{importCandidate=null;});}
function confirmDialog(title,body,action,label){const d=$('#confirm-dialog');d.innerHTML=`<div class="modal-header"><h2 id="confirm-title">${title}</h2><button class="icon-button" data-action="cancel-confirm" aria-label="確認を閉じる">×</button></div><div class="modal-body"><p>${body}</p><div class="save-row"><button class="button secondary" data-action="cancel-confirm">やめる</button><button class="button primary" data-action="${action}">${label}</button></div></div>`;d.showModal();}
async function canon(){stopAudio();const generation=audioGeneration;try{await ctx();if(generation!==audioGeneration)return;const s=SONGS.find(s=>s.id===selectedSong),events=parseNotes(s.notes),beat=60/state.settings.tempo,start=audio.currentTime+.1;playing=true;for(let i=0;i<4;i++)tone('B5',start+i*beat,.055,true);let end=0;for(const offset of [4,12]){let time=offset*beat;for(const e of events){tone(e.note,start+time,e.beats*beat*.85);time+=e.beats*beat;}end=time;}$$('.player-status').forEach(e=>e.textContent='８拍あとに、２人目が同じ曲で入ります。');timers.push(setTimeout(stopAudio,end*1000+200));}catch(e){stopAudio();toast(e.message);}}
document.addEventListener('click',async e=>{const t=e.target.closest('button,a,[data-note]');if(!t)return;if(t.dataset.page){e.preventDefault();route(t.dataset.page);return;}if(t.dataset.world!==undefined){world=Number(t.dataset.world);if(page!=='map'){route('map');}else{render();}$('.area-panel').scrollIntoView({behavior:'smooth',block:'start'});return;}if(t.dataset.lesson){openLesson(t.dataset.lesson);return;}if(t.dataset.song){stopAudio();selectedSong=t.dataset.song;segment='all';chosenNote=parseNotes(SONGS.find(s=>s.id===selectedSong).notes).find(n=>n.note!=='R').note;render();return;}if(t.dataset.pickNote){singleNote(t.dataset.pickNote);return;}if(t.dataset.note){if(t.dataset.note!=='R')singleNote(t.dataset.note);return;}if(t.dataset.addNote){if(state.composition.length>=32)return;stopAudio();state.composition.push({note:t.dataset.addNote,beats:composerBeat});save();render();return;}if(t.dataset.removeNote!==undefined){stopAudio();state.composition.splice(Number(t.dataset.removeNote),1);save();render();return;}
switch(t.dataset.action){case'play':play();break;case'stop':stopAudio();break;case'close-lesson':closeLesson();break;case'save-lesson':saveLesson();break;case'names':{state.settings.names=!state.settings.names;save();if(activeLesson){$$('.note-label').forEach(el=>{const n=el.closest('[data-note]').dataset.note;el.textContent=state.settings.names?(n==='R'?'休み':NOTES[n][0]):'';});t.textContent=`音名を${state.settings.names?'かくす':'出す'}`;}else{stopAudio();render();}break;}case'save-research':state.notes[$('#research-prompt').value]=$('#research-note').value;save();toast('発見をのこしたよ。次の実験も楽しみだね！');break;case'export':{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='recorder-quest-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('バックアップをダウンロードしました。');break;}case'reset':confirmDialog('記録をリセットする？','このブラウザの学習記録・曲・発見ノートが消えます。必要なら、先にバックアップしてください。','confirm-reset','リセットする');break;case'confirm-reset':state=fresh();save();render();toast('新しいぼうけんを始められるよ。');break;case'cancel-confirm':$('#confirm-dialog').close();importCandidate=null;break;case'confirm-import':if(importCandidate){state=importCandidate;importCandidate=null;save();render();toast('記録を読みこみました。');}break;case'canon':canon();break;}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-note]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
document.addEventListener('input',e=>{if(e.target.id==='tempo'){stopAudio();state.settings.tempo=Number(e.target.value);e.target.nextElementSibling.value=state.settings.tempo;save();}if(e.target.id==='composition-title'){state.compositionTitle=e.target.value;save();}if(e.target.id==='research-note'){state.notes[$('#research-prompt').value]=e.target.value;save();}});
document.addEventListener('change',async e=>{const t=e.target;if(t.matches('.step-check,input[name="rating"]'))checkLesson();if(t.id==='loop')loop=t.checked;if(t.id==='click-track'){clickTrack=t.checked;stopAudio();}if(t.id==='segment'){stopAudio();segment=t.value;render();}if(t.id==='articulation'){stopAudio();articulation=t.value;}if(t.id==='composer-beat')composerBeat=Number(t.value);if(t.id==='research-prompt'){$('#research-note').value=state.notes[t.value]||'';$('#research-question').textContent=LESSONS.find(l=>l.id===t.value).question;}
if(t.id==='import-file'){const f=t.files[0];if(!f)return;try{if(f.size>1000000)throw Error('ファイルが大きすぎます（上限１MB）');importCandidate=validateBackup(JSON.parse(await f.text()));confirmDialog('バックアップを読みこむ？',`${Object.keys(importCandidate.records).length}件の記録を読み込みます。今の記録・曲・発見ノートは置き換わります。`,'confirm-import','読みこむ');}catch(e){toast(e.message||'バックアップを読み込めませんでした。');}t.value='';}});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(nav.some(n=>n[0]===p)||p==='guide'){if(page!==p){stopAudio();activeLesson=null;page=p;render();}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAudio();});
render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'read_learning_progress',description:'Read device-local recorder learning progress and recommended lesson.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({completed:completed(state),points:earnedPoints(),recommended:recommend(state).lesson.id})},{name:'open_recorder_lesson',description:'Open a lesson without completing it or changing learning records.',inputSchema:{type:'object',properties:{lessonId:{type:'string'}},required:['lessonId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!LESSONS.some(l=>l.id===input.lessonId))throw Error('Unknown lesson');if(activeLesson)closeLesson();openLesson(input.lessonId);return {opened:input.lessonId};}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
